cat > ./fixer_test_tmp.php <<'EOF'
<?php
require_once '/testbed/vendor/autoload.php';

use PhpCsFixer\Tokenizer\Tokens;
use PhpCsFixer\Fixer\StringNotation\SimpleToComplexStringVariableFixer;

$fixer = new SimpleToComplexStringVariableFixer();
$cases = [
    ["<?php echo \"Hello \${name}!\";", "basic"],
    ["<?php echo \"Hello \${name['key']}!\";", "array key"],
    ["<?php echo \"Hello \${name[0]}!\";", "array index"],
    ["<?php \$name = ['k' => [1]]; echo \"Hello \${name['k']}!\";", "single-index chain"],
];
foreach ($cases as [$code, $label]) {
    $tokens = Tokens::fromCode($code);
    $fixer->fix(new SplFileInfo('t.php'), $tokens);
    echo $label, ": ", $tokens->generateCode(), PHP_EOL;
}
EOF
